{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts, assemble them at a specific spot on the workbench using a tool, then put the tool back on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_site",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["marked_spot", "assembly_point"],
        "required_properties": ["has_fastening_need"]
      },
      {
        "id": "fastener_piece",
        "entity_kind": "OBJECT",
        "function": "A physical part that fits into or onto the fastening site to complete the assembly.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screw", "nut", "bolt", "plate", "block"],
        "required_properties": ["compatible_with_fastening_site"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to secure the fastener piece to the site.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screwdriver", "wrench", "hammer", "glue"],
        "required_properties": ["suitable_for_fastening_type"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The top surface of the workbench where tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat_surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_01",
        "relation": "is_compatible_with",
        "participant_roles": ["fastener_piece", "fastening_site"]
      ,
      "required": true
      },
      {
        "id": "relation_02",
        "relation": "is_used_to_fasten",
        "participant_roles": ["fastening_tool", "fastener_piece", "fastening_site"]
      ,
      "required": true
      },
      {
        "id": "relation_03",
        "relation": "is_placed_on",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_01",
        "operation": "identify_components",
        "participant_roles": ["fastener_piece", "fastening_site"]
      ,
      "operation_count": 1
      },
      {
        "id": "op_02",
        "operation": "complete_fastening",
        "participant_roles": ["fastener_piece", "fastening_tool", "fastening_site"]
      ,
      "operation_count": 1
      },
      {
        "id": "op_03",
        "operation": "return_tool",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_site": [
        {
          "label": "tray_on_workbench",
          "visual_description": "A black tray with yellow and blue items sitting on the wooden workbench surface."
        }
      ],
      "fastener_piece": [
        {
          "label": "items_in_tray",
          "visual_description": "Yellow and blue rectangular objects inside the black tray."
        }
      ],
      "fastening_tool": [],
      "workbench_surface": [
        {
          "label": "wooden_table",
          "visual_description": "The wooden top of the desk/workbench."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "region_01",
        "label": "blue_cabinet",
        "visual_description": "A tall blue cabinet standing against the wall behind the workbench.",
        "reason": "Could contain hidden fasteners or tools."
      },
      {
        "id": "region_02",
        "label": "under_table_drawers",
        "visual_description": "Two blue drawers located underneath the workbench.",
        "reason": "Closed storage structures that could hold necessary components or tools."
      }
    ],
    "inspection_order": [
      "region_01",
      "region_02"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
